-1 text-sm text-slate-500">{{ $complaint->buyer->phone }} · Blok {{ $complaint->buyer->block }} No. {{ $complaint->buyer->house_number }} · {{ $complaint->created_at->format('d M Y H:i') }}</p></div><div class="text-right"><span class="rounded-full px-3 py-1 text-xs font-bold {{ $badges[$complaint->status] ?? 'bg-slate-100 text-slate-600' }}">{{ $tabs[$complaint->status] ?? $complaint->status }}</span><p class="mt-2 text-xs font-bold text-slate-500">{{ $categories[$complaint->category] ?? ucwords(str_replace('_', ' ', $complaint->category)) }}</p></div></div><p class="mt-5 rounded-xl bg-slate-50 p-4 text-sm leading-6">{{ $complaint->description }}</p>@if ($complaint->evidence_image)<figure class="mt-5"><img src="{{ Storage::disk('public')->url($complaint->evidence_image) }}" alt="Bukti foto komplain {{ $complaint->order->order_number }}" class="max-h-72 w-full rounded-xl border border-slate-200 object-cover"><figcaption><a href="{{ Storage::disk('public')->url($complaint->evidence_image) }}" target="_blank" class="mt-2 inline-block text-sm font-bold text-emerald-700">Lihat ukuran penuh &nearr;</a></figcaption></figure>@endif<form action="{{ route('admin.complaints.status', $complaint) }}" method="POST" class="mt-5 flex flex-wrap items-end gap-3">@csrf @method('PATCH')<label class="text-sm font-semibold">Update status<select name="status" required class="mt-1 block rounded-lg border-slate-300">@foreach ($tabs as $value => $label)<option value="{{ $value }}" @selected($complaint->status === $value)>{{ $label }}</option>@endforeach</select></label><button class="rounded-lg bg-emerald-800 px-4 py-2 text-sm font-bold text-white">Simpan status</button></form></article>@empty<div class="rounded-2xl bg-white p-12 text-center text-slate-500">Belum ada komplain{{ $status ? ' dengan status ini' : '' }}.</div>@endforelse</div></main></body></html>